result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "match3.py", "content": """"Match-3 cascade resolver.

Rules:
- A "run" is >=3 identical, non-empty gems contiguously horizontal or vertical.
- All runs on the board are cleared *simultaneously* each cascade step.
- After clearing, gravity is applied: gems fall straight down, holes rise to the top.
- Holes are refilled from a scripted per-column FIFO queue (front of list pops first,
  filling the topmost empty cell of that column). If a column's queue is empty, the
  hole remains (represented as None).
- Repeat (find -> clear -> gravity -> refill) until no runs remain ("stable").
- Scoring: each cleared gem is worth 10 points, multiplied by 2 ** (cascade_level - 1).
  So the first cascade wave scores 10/gem, the second 20/gem, the third 40/gem, etc.
"""

from copy import deepcopy


def find_runs(grid):
    """Return the set of (row, col) cells belonging to any run of length >= 3."""
    rows, cols = len(grid), len(grid[0])
    cells = set()
    for r in range(rows):
        c = 0
        while c < cols:
            v = grid[r][c]
            if v is None:
                c += 1
                continue
            e = c
            while e + 1 < cols and grid[r][e + 1] == v:
                e += 1
            if e - c + 1 >= 3:
                cells.update((r, i) for i in range(c, e + 1))
            c = e + 1
    for c in range(cols):
        r = 0
        while r < rows:
            v = grid[r][c]
            if v is None:
                r += 1
                continue
            e = r
            while e + 1 < rows and grid[e + 1][c] == v:
                e += 1
            if e - r + 1 >= 3:
                cells.update((i, c) for i in range(r, e + 1))
            r = e + 1
    return cells


def apply_gravity(grid):
    """Drop every non-None gem to the bottom of its column; holes float up."""
    rows, cols = len(grid), len(grid[0])
    for c in range(cols):
        stack = [grid[r][c] for r in range(rows) if grid[r][c] is not None]
        holes = rows - len(stack)
        for r in range(rows):
            grid[r][c] = stack[r - holes] if r >= holes else None


def refill(grid, queues):
    """Fill topmost holes per column from that column's FIFO queue (in place)."""
    rows, cols = len(grid), len(grid[0])
    for c in range(cols):
        for r in range(rows):
            if grid[r][c] is None:
                if queues.get(c):
                    grid[r][c] = queues[c].pop(0)


def has_matches(grid):
    return bool(find_runs(grid))


def resolve(grid, queues=None):
    """Resolve all cascades on a deep copy of `grid`.

    Returns (final_grid, score, cascade_count).
    """
    g = deepcopy(grid)
    queues = {k: list(v) for k, v in (queues or {}).items()}
    score = 0
    cascades = 0
    while True:
        runs = find_runs(g)
        if not runs:
            break
        cascades += 1
        score += 10 * len(runs) * 2 ** (cascades - 1)
        for r, c in runs:
            g[r][c] = None
        apply_gravity(g)
        refill(g, queues)
    return g, score, cascades


START_GRID = [
    ["R", "R", "G", "B", "B"],
    ["G", "R", "B", "B", "G"],
    ["R", "G", "R", "G", "B"],
    ["B", "B", "G", "R", "R"],
]

# Scripted refill queues used by the deterministic scenario test below.
REFILL_QUEUES = {
    0: ["Y"],
    1: ["Y"],
    2: ["P"],
}
"})
print(result)

